const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const galleries=[...document.querySelectorAll('.gallery')];
function centerSlide(gallery,index,behavior='smooth'){const slide=gallery.querySelectorAll('.slide')[index];if(!slide)return;gallery.scrollTo({left:slide.offsetLeft-gallery.offsetLeft-(gallery.clientWidth-slide.offsetWidth)/2,behavior:reduced.matches?'instant':behavior});}
galleries.forEach(gallery=>{const dots=[...gallery.nextElementSibling.querySelectorAll('button')];const slides=[...gallery.querySelectorAll('.slide')];dots.forEach((dot,i)=>dot.addEventListener('click',()=>centerSlide(gallery,i)));gallery.addEventListener('scroll',()=>{const center=gallery.getBoundingClientRect().left+gallery.clientWidth/2;const current=slides.reduce((best,slide,i)=>Math.abs(slide.getBoundingClientRect().left+slide.offsetWidth/2-center)<Math.abs(slides[best].getBoundingClientRect().left+slides[best].offsetWidth/2-center)?i:best,0);dots.forEach((dot,i)=>{dot.classList.toggle('active',i===current);dot.setAttribute('aria-pressed',String(i===current));});},{passive:true});gallery.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const current=dots.findIndex(d=>d.classList.contains('active'));centerSlide(gallery,Math.max(0,Math.min(slides.length-1,current+(e.key==='ArrowRight'?1:-1))));});});
function initializeGalleries(){galleries.forEach(g=>centerSlide(g,1,'instant'));}requestAnimationFrame(initializeGalleries);window.addEventListener('load',initializeGalleries,{once:true});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(initializeGalleries,150);});
const theme=document.querySelector('.theme-toggle');let saved;try{saved=localStorage.getItem('portfolio-theme');}catch{}
function setTheme(light){document.documentElement.classList.toggle('light',light);theme.setAttribute('aria-pressed',String(light));theme.setAttribute('aria-label',light?'Включить тёмную тему':'Включить светлую тему');}
setTheme(saved==='light');theme.addEventListener('click',()=>{const light=!document.documentElement.classList.contains('light');setTheme(light);try{localStorage.setItem('portfolio-theme',light?'light':'dark');}catch{}});
const dialog=document.querySelector('dialog');let opener;
const closeDialog=()=>{dialog.close();document.body.style.overflow='';opener?.focus();};
document.querySelector('.close-button').addEventListener('click',closeDialog);dialog.addEventListener('cancel',()=>{document.body.style.overflow='';});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
document.querySelectorAll('[data-open-project]').forEach(button=>button.addEventListener('click',()=>{opener=button;const id=button.dataset.openProject;const body=document.querySelector('#dialog-body');body.replaceChildren();document.querySelector('#dialog-title').textContent=id==='archive'?'Концепты и старые проекты':id==='designers'?'Дизайнерс':'Совкомбанк';if(id==='archive'){const p=document.createElement('p');p.className='dialog-copy';p.textContent='Больше проектов и подробности о работе — по запросу.';body.append(p);const a=document.createElement('a');a.className='dialog-contact';a.href='https://t.me/malasa1308';a.target='_blank';a.rel='noopener noreferrer';a.textContent='Написать в Telegram ↗';body.append(a);}else{const section=document.getElementById(id);const copy=section.querySelector('.description').cloneNode(true);copy.className='dialog-copy';body.append(copy);const list=document.createElement('div');list.className='dialog-gallery';section.querySelectorAll('.slide').forEach(slide=>list.append(slide.cloneNode(true)));body.append(list);}dialog.showModal();document.body.style.overflow='hidden';requestAnimationFrame(()=>{body.querySelectorAll('.slide').forEach(slide=>{const width=parseFloat(slide.style.getPropertyValue('--slide-width'));slide.style.setProperty('--art-scale',Math.min(1,(body.clientWidth-4)/width));});});}));
document.querySelectorAll('[data-cv]').forEach(button=>button.addEventListener('click',()=>{opener=button;document.querySelector('#dialog-title').textContent='Резюме';const body=document.querySelector('#dialog-body');body.innerHTML='<p class="dialog-copy">Актуальное резюме можно запросить по почте или в Telegram.</p><a class="dialog-contact" href="mailto:malasa1308@gmail.com?subject=Запрос%20резюме">malasa1308@gmail.com ↗</a><br><a class="dialog-contact" href="https://t.me/malasa1308" target="_blank" rel="noopener noreferrer">Написать в Telegram ↗</a>';dialog.showModal();document.body.style.overflow='hidden';}));
